import http from "k6/http";
import { check, sleep } from "k6";

export const options = {
  vus: 5,
  duration: "20s",
  thresholds: {
    http_req_failed: ["rate<0.01"],
    http_req_duration: ["p(95)<800"]
  }
};

const BASE_URL = "http://localhost:4000";

function randomEmail(prefix) {
  return `${prefix}-${Date.now()}-${Math.floor(Math.random() * 100000)}@test.com`;
}

export default function () {
  const signupPayload = JSON.stringify({
    fullName: "k6 Customer",
    email: randomEmail("k6-customer"),
    password: "Password123"
  });

  const signupRes = http.post(`${BASE_URL}/api/auth/customer/signup`, signupPayload, {
    headers: {
      "Content-Type": "application/json"
    }
  });

  check(signupRes, {
    "customer signup status is 201": (r) => r.status === 201
  });

  const signupBody = signupRes.json();
  const token = signupBody?.data?.accessToken;

  check(token, {
    "customer token exists": (t) => !!t
  });

  if (!token) {
    return;
  }

  const topUpPayload = JSON.stringify({
    amount: 100
  });

  const topUpRes = http.post(`${BASE_URL}/api/wallet/top-up`, topUpPayload, {
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`
    }
  });

  check(topUpRes, {
    "wallet top-up status is 200": (r) => r.status === 200
  });

  sleep(1);
}

